            if(method==="account/read")return {account:this.account};if(method==="skills/list")return {data:[{cwd:runtime,skills:this.skills,errors:[]}]};if(method==="model/list")return {data:this.models,nextCursor:null};if(method==="thread/list")return {data:[this.thread],nextCursor:"thread-next"};if(method==="thread/read" || method==="thread/resume" || method==="thread/start")return {thread:this.thread};if(method==="thread/turns/list")return {data:[{id:"turn-old",status:this.turnStatus}]};if(method==="thread/items/list")return {data:[{turnId:"turn-old",item:{id:"assistant-old",type:"agentMessage",text:"Trả lời trước"}},{turnId:"turn-old",item:{id:"user-old",type:"userMessage",content:[{type:"text",text:"Yêu cầu trước"}]}}],nextCursor:"history-next"};if(method==="turn/start")return {turn:{id:"turn-new",status:"inProgress"}};if(method==="turn/interrupt"){if(this.completeOnInterrupt)setImmediate(()=>this.emit("notification",{method:"turn/completed",params:{threadId:this.thread.id,turn:{id:"turn-new",status:"interrupted"}}}));return {};}
